def casefold_predecessor_selection(selection):
    require(isinstance(selection, dict) and selection.get('casefold_fixture_repair') == CASEFOLD_LAYER,
            'Missing/changed casefold fixture repair')
    layer = selection['casefold_fixture_repair']
    require(set(layer) == {'version', 'name', 'base_commit', 'base_tree', 'allowed_changes', 'diagnostic_before_blobs'}
            and type(layer['version']) is int and layer['version'] == 1
            and layer['name'] == CASEFOLD_NAME and layer['base_commit'] == CASEFOLD_BASE_COMMIT
            and layer['base_tree'] == CASEFOLD_BASE_TREE
            and layer['allowed_changes'] == ['M\t' + p for p in CASEFOLD_PATHS]
            and layer['diagnostic_before_blobs'] == CASEFOLD_BEFORE_BLOBS,
            'Changed independently fixed casefold fields or predecessors')
    require(hashlib.sha256(encode(selection).encode()).hexdigest() == CASEFOLD_SELECTION_SHA256,
            'Changed complete casefold selection')
    old = {k: v for k, v in selection.items() if k != 'casefold_fixture_repair'}
    raw = (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode()
    require(hashlib.sha256(raw).hexdigest() == CASEFOLD_PRE_SELECTION_SHA256
            and blob_id(raw) == CASEFOLD_BEFORE_BLOBS[CASEFOLD_PATHS[1]]
            and CASEFOLD_PRE_SELECTION_SHA256 == PATHFIX_SELECTION_RAW_SHA256,
            'Complete published54 selection not restored')
    return json.loads(raw, object_pairs_hook=unique_object)


def casefold_current_inputs(selection, root):
    casefold_predecessor_selection(selection)
    require(root.is_dir() and not root.is_symlink(), 'Casefold root is not a real directory')
    incoming = {}
    for relative in CASEFOLD_PATHS:
        parts = Path(relative).parts
        path = root / relative
        require(all(not (root / Path(*parts[:i])).is_symlink() for i in range(1, len(parts) + 1))
                and path.is_file() and path.resolve(strict=True).is_relative_to(root.resolve(strict=True)),
                'Casefold current source missing, linked, or outside root: ' + relative)
        incoming[relative] = path.read_bytes()
    require(hashlib.sha256(incoming[CASEFOLD_PATHS[0]]).hexdigest() == NATIVE_IMPLEMENTATION_SHA256,
            'Casefold runner differs from complete loaded implementation')
    require(hashlib.sha256(incoming[CASEFOLD_PATHS[1]]).hexdigest() == CASEFOLD_SELECTION_RAW_SHA256
            and json.loads(incoming[CASEFOLD_PATHS[1]], object_pairs_hook=unique_object) == selection,
            'Changed complete raw casefold selection')
    require(hashlib.sha256(incoming[CASEFOLD_PATHS[2]]).hexdigest() == CASEFOLD_TEST_SHA256,
            'Changed complete casefold diagnostic tests')
    return incoming


def casefold_predecessor_sources(selection, root):
    incoming = casefold_current_inputs(selection, root)
    old = casefold_predecessor_selection(selection)
    test = zlib.decompress(base64.b85decode(CASEFOLD_PRE_TEST_PACKED))
    require(hashlib.sha256(test).hexdigest() == CASEFOLD_PRE_TEST_SHA256
            and blob_id(test) == CASEFOLD_BEFORE_BLOBS[CASEFOLD_PATHS[2]]
            and CASEFOLD_PRE_TEST_SHA256 == PATHFIX_TEST_SHA256,
            'Changed complete published54 diagnostic predecessor')
    return {CASEFOLD_PATHS[0]: incoming[CASEFOLD_PATHS[0]],
            CASEFOLD_PATHS[1]: (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode(), CASEFOLD_PATHS[2]: test}


def casefold_pathfix_selection(root, *, casefold_layer=False):
    current = read_json(root / CASEFOLD_PATHS[1])
    if casefold_layer:
        casefold_current_inputs(current, root)
        current = casefold_predecessor_selection(current)
    return current


def validate_casefold_selection(selection, root):
    old = casefold_predecessor_selection(selection)
    casefold_predecessor_sources(selection, root)
    validate_pathfix_selection(old, root, casefold_layer=True)
    return selection


def verify_casefold_tree(root, revision, *, before):
    incoming = casefold_current_inputs(read_json(root / CASEFOLD_PATHS[1]), root)
    expected = CASEFOLD_BEFORE_BLOBS if before else {p: blob_id(incoming[p]) for p in CASEFOLD_PATHS}
    actual = {}
    for entry in checked(['git', 'ls-tree', '-z', revision, '--', *CASEFOLD_PATHS], root).split('\0'):
        if not entry: continue
        meta, path = entry.split('\t', 1)
        require(path not in actual, 'Duplicate casefold tree path')
        actual[path] = meta.split(' ')
    require(set(actual) == set(expected), 'Missing/unexpected casefold tree path')
    for path, oid in expected.items():
        require(actual[path] == ['100644', 'blob', oid], 'Changed casefold mode/blob: ' + path)
    return actual


def verify_casefold_scope(root, selection):
    validate_casefold_selection(selection, root)
    head = checked(['git', 'rev-parse', 'HEAD'], root)
    require(re.fullmatch('[a-f0-9]{40}', head) is not None and head == os.environ.get('GITHUB_SHA'),
            'Actual casefold HEAD differs from GITHUB_SHA')
    headers = checked(['git', 'cat-file', '-p', head], root).split('\n\n', 1)[0].splitlines()
    require([line[7:] for line in headers if line.startswith('parent ')] == [CASEFOLD_BASE_COMMIT],
            'Casefold repair must have exactly published54 parent')
    require(checked(['git', 'rev-parse', CASEFOLD_BASE_COMMIT + '^{tree}'], root) == CASEFOLD_BASE_TREE,
            'Changed complete published54 tree')
    changes = checked(['git', 'diff', '--name-status', CASEFOLD_BASE_COMMIT, head], root).splitlines()
    require(len(changes) == 3 and set(changes) == set(CASEFOLD_LAYER['allowed_changes']),
            'Casefold repair differs from three exact modifications')
    verify_casefold_tree(root, CASEFOLD_BASE_COMMIT, before=True)
    verify_casefold_tree(root, head, before=False)
    ensure_pathfix_commit(root)
    prior = verify_pathfix_scope(root, casefold_predecessor_selection(selection),
                                published_revision=CASEFOLD_BASE_COMMIT)
    prior.update(source_sha=head, source_tree=checked(['git', 'rev-parse', 'HEAD^{tree}'], root),
                 casefold_base_commit=CASEFOLD_BASE_COMMIT, casefold_base_tree=CASEFOLD_BASE_TREE,
                 casefold_selection=CASEFOLD_NAME)
    require(not checked(['git', 'status', '--porcelain', '--untracked-files=normal'], root),
            'Casefold checkout is not clean')
    return prior


def validate_casefold_pass_receipt(receipt, expected, selection):
    require(receipt.get('casefold_base_commit') == CASEFOLD_BASE_COMMIT
            and receipt.get('casefold_base_tree') == CASEFOLD_BASE_TREE
            and receipt.get('casefold_selection') == CASEFOLD_NAME, 'Wrong casefold receipt identity')
    validate_pathfix_pass_receipt(receipt, expected, casefold_predecessor_selection(selection))


def pathfix_predecessor_selection(selection):
    """Authenticate the complete eleven-path layer, then restore exact published bb5."""
    require(PATHFIX_DIAGNOSTIC_PATHS == SOCIAL_DIAGNOSTIC_PATHS
            and PATHFIX_PATHS == PATHFIX_DIAGNOSTIC_PATHS + PATHFIX_PAYLOAD_PATHS
            and {p: PATHFIX_BEFORE_BLOBS[p] for p in PATHFIX_DIAGNOSTIC_PATHS} == {
                PATHFIX_PATHS[0]: PATHFIX_PRE_RUNNER_BLOB,
                PATHFIX_PATHS[1]: PATHFIX_PRE_SELECTION_BLOB,
                PATHFIX_PATHS[2]: PATHFIX_PRE_TEST_BLOB},
            'Changed independently fixed published bb5 diagnostic predecessors')
    require(isinstance(selection, dict) and selection.get('xctestrun_path_repair') == PATHFIX_LAYER,
            'Missing/changed exact eleven-path xctestrun layer')
    layer = selection['xctestrun_path_repair']
    require(set(layer) == {'version', 'name', 'base_commit', 'base_tree', 'allowed_changes',
                          'diagnostic_before_blobs', 'payload_changes'}
            and type(layer['version']) is int and layer['version'] == 1
            and layer['name'] == PATHFIX_NAME
            and layer['base_commit'] == PATHFIX_BASE_COMMIT
            and layer['base_tree'] == PATHFIX_BASE_TREE,
            'Changed pathfix layer fields/version/published identity')
    require(layer['allowed_changes'] == ['M\t' + path for path in PATHFIX_PATHS]
            and layer['diagnostic_before_blobs'] == {path: PATHFIX_BEFORE_BLOBS[path] for path in PATHFIX_DIAGNOSTIC_PATHS},
            'Changed independently fixed pathfix statuses/predecessors')
    rows = layer['payload_changes']
    require(isinstance(rows, list) and all(isinstance(row, dict) for row in rows)
            and [row.get('path') for row in rows] == list(PATHFIX_PAYLOAD_PATHS)
            and hashlib.sha256(encode(rows).encode()).hexdigest() == PATHFIX_PAYLOAD_ROWS_SHA256,
            'Changed independently fixed eleven-path payload bindings')
    require(hashlib.sha256(encode(selection).encode()).hexdigest() == PATHFIX_SELECTION_SHA256,
            'Changed complete pathfix selection')
    old = {key: value for key, value in selection.items() if key != 'xctestrun_path_repair'}
    raw = (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode()
    require(hashlib.sha256(raw).hexdigest() == PATHFIX_PRE_SELECTION_SHA256
            and blob_id(raw) == PATHFIX_PRE_SELECTION_BLOB
            and PATHFIX_PRE_SELECTION_BLOB == PATHFIX_BEFORE_BLOBS[PATHS[1]],
            'Complete published bb5 selection not restored')
    return json.loads(raw, object_pairs_hook=unique_object)


def pathfix_current_inputs(selection, root, *, casefold_layer=False):
    """Read and authenticate all eleven real current files on every invocation."""
    pathfix_predecessor_selection(selection)
    predecessors = {}
    if casefold_layer:
        current = read_json(root / PATHS[1])
        predecessors = casefold_predecessor_sources(current, root)
        require(casefold_predecessor_selection(current) == selection,
                'Changed casefold historical pathfix selection')
    incoming = {}
    for relative in PATHFIX_PATHS:
        path = root / relative
        parts = Path(relative).parts
        require(all(not (root / Path(*parts[:end])).is_symlink()
                    for end in range(1, len(parts) + 1)),
                'Pathfix source contains a symbolic-link component: ' + relative)
        require(not path.is_symlink() and path.is_file()
                and path.resolve().is_relative_to(root.resolve()),
                'Pathfix source is not a regular in-root current file: ' + relative)
        raw = path.read_bytes()
        incoming[relative] = predecessors.get(relative, raw)
    require(hashlib.sha256(incoming[PATHFIX_PATHS[0]]).hexdigest() == NATIVE_IMPLEMENTATION_SHA256,
            'Pathfix runner differs from authenticated loaded implementation')
    require(hashlib.sha256(incoming[PATHFIX_PATHS[1]]).hexdigest() == PATHFIX_SELECTION_RAW_SHA256
            and json.loads(incoming[PATHFIX_PATHS[1]], object_pairs_hook=unique_object) == selection,
            'Changed complete current pathfix selection bytes')
    require(hashlib.sha256(incoming[PATHFIX_PATHS[2]]).hexdigest() == PATHFIX_TEST_SHA256,
            'Changed complete current pathfix diagnostic controls')
    for row in PATHFIX_LAYER['payload_changes']:
        require(set(row) == {'path', 'status', 'before_sha256', 'before_blob',
                            'after_sha256', 'after_blob', 'hunks'} and row['status'] == 'M'
                and (row['before_sha256'], row['before_blob']) == PATHFIX_PAYLOAD_PREIMAGES[row['path']]
                and row['before_blob'] == PATHFIX_BEFORE_BLOBS[row['path']],
                'Changed fixed album payload predecessor')
        require(hashlib.sha256(incoming[row['path']]).hexdigest() == row['after_sha256']
                and blob_id(incoming[row['path']]) == row['after_blob'],
                'Changed complete current album payload: ' + row['path'])
    return incoming


def pathfix_predecessor_sources(selection, root, *, casefold_layer=False):
    """Restore fixed bb5 diagnostic identities only after raw current11 authentication."""
    incoming = pathfix_current_inputs(selection, root, casefold_layer=casefold_layer)
    old_selection = pathfix_predecessor_selection(selection)
    raw_selection = (json.dumps(old_selection, indent=2, ensure_ascii=True) + '\n').encode()
    old_test = zlib.decompress(base64.b85decode(PATHFIX_PRE_TEST_PACKED))
    require(hashlib.sha256(old_test).hexdigest() == PATHFIX_PRE_TEST_SHA256
            and blob_id(old_test) == PATHFIX_PRE_TEST_BLOB
            and PATHFIX_PRE_TEST_BLOB == PATHFIX_BEFORE_BLOBS[PATHFIX_PATHS[2]]
            and PATHFIX_PRE_TEST_SHA256 == SOCIAL_TEST_SHA256
            and PATHFIX_PRE_SELECTION_SHA256 == SOCIAL_SELECTION_RAW_SHA256,
            'Changed independently fixed published bb5 diagnostic predecessor authority')
    restored = {PATHFIX_PATHS[0]: incoming[PATHFIX_PATHS[0]],
                PATHFIX_PATHS[1]: raw_selection, PATHFIX_PATHS[2]: old_test}
    for row in PATHFIX_LAYER['payload_changes']:
        restored[row['path']] = inverse_reviewed_repair(row, incoming[row['path']])
        require(blob_id(restored[row['path']]) == PATHFIX_BEFORE_BLOBS[row['path']],
                'Wrong complete bb5 album payload predecessor')
    return restored


def pathfix_social_selection(root, *, pathfix_layer=False, casefold_layer=False):
    """Explicit source entry; default historical callers never admit the new layer."""
    current = casefold_pathfix_selection(root, casefold_layer=casefold_layer)
    if pathfix_layer:
        pathfix_current_inputs(current, root, casefold_layer=casefold_layer)
        current = pathfix_predecessor_selection(current)
    return current


def validate_pathfix_selection(selection, root, *, casefold_layer=False):
    old = pathfix_predecessor_selection(selection)
    pathfix_predecessor_sources(selection, root, casefold_layer=casefold_layer)
    validate_social_selection(old, root, pathfix_layer=True, casefold_layer=casefold_layer)
    return selection


def verify_pathfix_tree(root, revision, *, before, casefold_layer=False, published_blobs=None):
    incoming = pathfix_current_inputs(casefold_pathfix_selection(root, casefold_layer=casefold_layer), root, casefold_layer=casefold_layer)
    expected = PATHFIX_BEFORE_BLOBS if before else {
        path: blob_id(incoming[path]) for path in PATHFIX_PATHS}
    if published_blobs is not None:
        require(published_blobs == CASEFOLD_PATHFIX_AFTER_BLOBS and not before
                and revision == CASEFOLD_BASE_COMMIT, 'Unknown published54 pathfix tree authority')
        expected = published_blobs
    raw = checked(['git', 'ls-tree', '-z', revision, '--', *PATHFIX_PATHS], root)
    actual = {}
    for entry in raw.split('\0'):
        if not entry:
            continue
        metadata, path = entry.split('\t', 1)
        require(path not in actual, 'Duplicate pathfix tree path')
        actual[path] = metadata.split(' ')
    require(set(actual) == set(expected), 'Missing/unexpected pathfix tree path')
    for path, blob in expected.items():
        require(actual[path] == ['100644', 'blob', blob], 'Changed pathfix mode/blob: ' + path)
    return actual


def verify_pathfix_scope(root, selection, *, published_revision=None):
    if published_revision is None:
        validate_pathfix_selection(selection, root)
        head = checked(['git', 'rev-parse', 'HEAD'], root)
        require(re.fullmatch('[a-f0-9]{40}', head) is not None
                and head == os.environ.get('GITHUB_SHA'), 'Actual pathfix HEAD differs from GITHUB_SHA')
    else:
        require(published_revision == CASEFOLD_BASE_COMMIT, 'Unknown published54 pathfix scope')
        current = read_json(root / PATHS[1])
        validate_casefold_selection(current, root)
        require(casefold_predecessor_selection(current) == selection, 'Changed complete published54 selection')
        head = published_revision
        require(checked(['git', 'rev-parse', head + '^{tree}'], root) == CASEFOLD_BASE_TREE,
                'Changed published54 pathfix tree')
    headers = checked(['git', 'cat-file', '-p', head], root).split('\n\n', 1)[0].splitlines()
    require([line[7:] for line in headers if line.startswith('parent ')] == [PATHFIX_BASE_COMMIT],
            'Pathfix repair must have exactly published bb5 parent')
    require(checked(['git', 'rev-parse', PATHFIX_BASE_COMMIT + '^{tree}'], root) == PATHFIX_BASE_TREE,
            'Changed published bb5 tree')
    changes = checked(['git', 'diff', '--name-status', PATHFIX_BASE_COMMIT, head], root).splitlines()
    require(len(changes) == 11 and set(changes) == set(PATHFIX_LAYER['allowed_changes']),
            'Pathfix repair differs from eleven exact modification statuses')
    verify_pathfix_tree(root, PATHFIX_BASE_COMMIT, before=True, casefold_layer=published_revision is not None)
    verify_pathfix_tree(root, head, before=False, casefold_layer=published_revision is not None,
                        published_blobs=CASEFOLD_PATHFIX_AFTER_BLOBS if published_revision else None)
    ensure_social_commit(root)
    prior = verify_social_scope(root, pathfix_predecessor_selection(selection),
                                published_revision=PATHFIX_BASE_COMMIT, casefold_layer=published_revision is not None)
    prior.update(source_sha=head, source_tree=checked(['git', 'rev-parse', (published_revision or 'HEAD') + '^{tree}'], root),
                 pathfix_base_commit=PATHFIX_BASE_COMMIT, pathfix_base_tree=PATHFIX_BASE_TREE,
                 pathfix_selection=PATHFIX_NAME)
    require(not checked(['git', 'status', '--porcelain', '--untracked-files=normal'], root),
            'Pathfix checkout is not clean')
    return prior


def validate_pathfix_pass_receipt(receipt, expected, selection):
    require(receipt.get('pathfix_base_commit') == PATHFIX_BASE_COMMIT
            and receipt.get('pathfix_base_tree') == PATHFIX_BASE_TREE
            and receipt.get('pathfix_selection') == PATHFIX_NAME,
            'Wrong receipt xctestrun pathfix identity')
    validate_social_pass_receipt(receipt, expected, pathfix_predecessor_selection(selection))


def social_predecessor_selection(selection):
    """Authenticate the full new layer before reconstructing published42 bytes."""
    require(isinstance(selection, dict) and selection.get('social_repair') == SOCIAL_LAYER,
            'Missing/changed exact fifteen-path social layer')
    layer = selection['social_repair']
    require(set(layer) == {'version', 'name', 'base_commit', 'base_tree', 'allowed_changes',
                          'payload_changes', 'diagnostic_before_blobs'}
            and type(layer['version']) is int and layer['version'] == 1
            and layer['name'] == 'social-actor-lifecycle-repair-v9'
            and layer['base_commit'] == SOCIAL_BASE_COMMIT
            and layer['base_tree'] == SOCIAL_BASE_TREE,
            'Changed social layer fields/version/published identity')
    require(layer['allowed_changes'] == [SOCIAL_STATUSES[path] + '\t' + path for path in SOCIAL_PATHS]
            and layer['diagnostic_before_blobs'] == {
                path: SOCIAL_BEFORE_BLOBS[path] for path in SOCIAL_DIAGNOSTIC_PATHS},
            'Changed independently fixed social statuses/diagnostic predecessors')
    rows = layer['payload_changes']
    require(isinstance(rows, list) and all(isinstance(row, dict) for row in rows)
            and [row.get('path') for row in rows] == list(SOCIAL_PAYLOAD_PATHS)
            and hashlib.sha256(encode(rows).encode()).hexdigest() == SOCIAL_REPAIR_CHANGES_SHA256,
            'Changed independently frozen ordered social payload bindings')
    require(hashlib.sha256(encode(selection).encode()).hexdigest() == SOCIAL_SELECTION_SHA256,
            'Changed complete social selection')
    old = {key: value for key, value in selection.items() if key != 'social_repair'}
    raw = (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode()
    require(hashlib.sha256(raw).hexdigest() == SOCIAL_PRE_SELECTION_SHA256
            and blob_id(raw) == SOCIAL_BEFORE_BLOBS[PATHS[1]],
            'Complete published42 selection not restored')
    return json.loads(raw, object_pairs_hook=unique_object)


def social_predecessor_sources(selection, root, *, pathfix_layer=False, casefold_layer=False):
    """Read all fifteen real current files; authenticate and invert twelve payloads."""
    social_predecessor_selection(selection)
    pathfix_sources = {}
    if pathfix_layer:
        current = casefold_pathfix_selection(root, casefold_layer=casefold_layer)
        pathfix_sources = pathfix_predecessor_sources(current, root, casefold_layer=casefold_layer)
        require(pathfix_predecessor_selection(current) == selection,
                'Pathfix historical social selection mismatch')
    incoming = {}
    for relative in SOCIAL_PATHS:
        path = root / relative
        parts = Path(relative).parts
        require(all(not (root / Path(*parts[:end])).is_symlink()
                    for end in range(1, len(parts) + 1)),
                'Social source contains a symbolic-link component: ' + relative)
        require(not path.is_symlink() and path.is_file()
                and path.resolve().is_relative_to(root.resolve()),
                'Social source is not a regular in-root current file: ' + relative)
        current_raw = path.read_bytes()
        incoming[relative] = pathfix_sources.get(relative, current_raw)
    require(hashlib.sha256(incoming[SOCIAL_DIAGNOSTIC_PATHS[0]]).hexdigest() == NATIVE_IMPLEMENTATION_SHA256,
            'Social runner differs from authenticated loaded implementation')
    require(hashlib.sha256(incoming[PATHS[1]]).hexdigest() == SOCIAL_SELECTION_RAW_SHA256,
            'Changed complete current social selection bytes')
    require(hashlib.sha256(incoming[SOCIAL_DIAGNOSTIC_PATHS[2]]).hexdigest() == SOCIAL_TEST_SHA256,
            'Changed complete current social diagnostic controls')
    restored = {}
    for row in SOCIAL_LAYER['payload_changes']:
        raw = incoming[row['path']]
        require(hashlib.sha256(raw).hexdigest() == row['after_sha256'] and blob_id(raw) == row['after_blob'],
                'Changed exact social payload: ' + row['path'])
        if row['path'] in SOCIAL_ADDITIONS:
            require(row['status'] == 'A' and row['before_sha256'] is None and row['before_blob'] is None
                    and row['hunks'] == [] and SOCIAL_BEFORE_BLOBS[row['path']] is None
                    and (row['after_sha256'], row['after_blob']) == SOCIAL_ADDITIONS[row['path']],
                    'Changed exact addition or fabricated social predecessor: ' + row['path'])
            restored[row['path']] = None
        else:
            require(row['status'] == 'M', 'Changed social modification status')
            restored[row['path']] = inverse_reviewed_repair(row, raw)
            require(blob_id(restored[row['path']]) == SOCIAL_BEFORE_BLOBS[row['path']],
                    'Wrong complete42 social predecessor: ' + row['path'])
    require(set(restored) == set(SOCIAL_PAYLOAD_PATHS), 'Incomplete social predecessor set')
    return restored


def validate_social_selection(selection, root, *, pathfix_layer=False, casefold_layer=False):
    old = social_predecessor_selection(selection)
    social_predecessor_sources(selection, root, pathfix_layer=pathfix_layer, casefold_layer=casefold_layer)
    # Published portable4 is independently fixed; current entry bytes remain
    # mandatory and its two-line predecessor is checked by the native14 path.
    require(digest(root / 'tools/tests/test_run138_current_ci_entry.py') ==
            PORTABLE_SOURCE_ROWS['tools/tests/test_run138_current_ci_entry.py']['after_sha256'],
            'Social current entry test differs from published42')
    validate_description_selection(old, root, social_layer=True, pathfix_layer=pathfix_layer, casefold_layer=casefold_layer)
    return selection


def verify_social_tree(root, revision, *, before, published_blobs=None):
    expected = {path: blob for path, blob in SOCIAL_BEFORE_BLOBS.items() if blob is not None} if before else {
        path: blob_id((root / path).read_bytes()) for path in SOCIAL_PATHS}
    if published_blobs is not None:
        require(published_blobs == PATHFIX_SOCIAL_AFTER_BLOBS and not before
                and revision == PATHFIX_BASE_COMMIT,
                'Unknown published social tree authority')
        expected = published_blobs
    raw = checked(['git', 'ls-tree', '-z', revision, '--', *SOCIAL_PATHS], root)
    actual = {}
    for entry in raw.split('\0'):
        if not entry: continue
        metadata, path = entry.split('\t', 1)
        require(path not in actual, 'Duplicate social tree path')
        actual[path] = metadata.split(' ')
    require(set(actual) == set(expected), 'Missing/unexpected social tree path or fabricated predecessor')
    for path, blob in expected.items():
        require(actual[path] == ['100644', 'blob', blob], 'Changed social mode/blob: ' + path)
    return actual


def verify_social_scope(root, selection, *, published_revision=None, casefold_layer=False):
    if published_revision is None:
        validate_social_selection(selection, root)
        head = checked(['git', 'rev-parse', 'HEAD'], root)
        require(re.fullmatch('[a-f0-9]{40}', head) is not None
                and head == os.environ.get('GITHUB_SHA'), 'Actual social HEAD differs from GITHUB_SHA')
    else:
        require(published_revision == PATHFIX_BASE_COMMIT, 'Unknown published social scope revision')
        current = casefold_pathfix_selection(root, casefold_layer=casefold_layer)
        validate_pathfix_selection(current, root, casefold_layer=casefold_layer)
        require(pathfix_predecessor_selection(current) == selection,
                'Changed complete published bb5 social selection')
        head = published_revision
        require(checked(['git', 'rev-parse', head + '^{tree}'], root) == PATHFIX_BASE_TREE,
                'Changed published bb5 social scope tree')
    headers = checked(['git', 'cat-file', '-p', head], root).split('\n\n', 1)[0].splitlines()
    require([line[7:] for line in headers if line.startswith('parent ')] == [SOCIAL_BASE_COMMIT],
            'Social repair must have exactly published42 parent')
    require(checked(['git', 'rev-parse', SOCIAL_BASE_COMMIT + '^{tree}'], root) == SOCIAL_BASE_TREE,
            'Changed published42 tree')
    changes = checked(['git', 'diff', '--name-status', SOCIAL_BASE_COMMIT, head], root).splitlines()
    require(len(changes) == 15 and set(changes) == set(SOCIAL_LAYER['allowed_changes']),
            'Social repair differs from fifteen exact statuses')
    verify_social_tree(root, SOCIAL_BASE_COMMIT, before=True)
    verify_social_tree(root, head, before=False,
                       published_blobs=PATHFIX_SOCIAL_AFTER_BLOBS if published_revision else None)
    ensure_description_commit(root)
    prior = verify_description_scope(root, social_predecessor_selection(selection),
                                  published_revision=SOCIAL_BASE_COMMIT, pathfix_layer=published_revision is not None, casefold_layer=casefold_layer)
    prior.update(source_sha=head, source_tree=checked(['git', 'rev-parse', (published_revision or 'HEAD') + '^{tree}'], root),
                 social_base_commit=SOCIAL_BASE_COMMIT,
                 social_base_tree=SOCIAL_BASE_TREE,
                 social_selection=SOCIAL_LAYER['name'])
    require(not checked(['git', 'status', '--porcelain', '--untracked-files=normal'], root),
            'Social checkout is not clean')
    return prior


def validate_social_pass_receipt(receipt, expected, selection):
    require(receipt.get('social_base_commit') == SOCIAL_BASE_COMMIT
            and receipt.get('social_base_tree') == SOCIAL_BASE_TREE
            and receipt.get('social_selection') == SOCIAL_LAYER['name'],
            'Wrong receipt social repair identity')
    validate_description_pass_receipt(receipt, expected, social_predecessor_selection(selection))


def description_predecessor_selection(selection):
    """Authenticate the full new layer before reconstructing published 7b bytes."""
    require(isinstance(selection, dict) and selection.get('description_repair') == DESCRIPTION_LAYER,
            'Missing/changed exact eleven-path description layer')
